// 1. Input Validation and Rejection Handling
if (ra_input.current_q_bi == NULL || ra_input.target_q_bi == NULL || ra_input.body_rate_rad_s == NULL) {
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

if ((ra_input.enable != 0 && ra_input.enable != 1) || (ra_input.valid != 0 && ra_input.valid != 1)) {
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

if (ra_input.valid == 0) {
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

if (!isfinite(ra_input.body_rate_rad_s->x) || !isfinite(ra_input.body_rate_rad_s->y) || !isfinite(ra_input.body_rate_rad_s->z)) {
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

adcs_quat_t q_curr_norm, q_target_norm;
if (adcs_quat_normalize(ra_input.current_q_bi, &q_curr_norm) != ADCS_OK) {
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}
if (adcs_quat_normalize(ra_input.target_q_bi, &q_target_norm) != ADCS_OK) {
    ra_state.bad_samples++;
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

// 2. Handle Disable / OFF Mode Reset
if (ra_input.enable == 0) {
    ra_state.mode = RA_OFF;
    ra_state.transition_samples = 0;
    ra_state.bad_samples = 0;
    ra_state.integral_error_rad_s.x = 0.0;
    ra_state.integral_error_rad_s.y = 0.0;
    ra_state.integral_error_rad_s.z = 0.0;

    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

// If in FAULT, stay there until Disable
if (ra_state.mode == RA_FAULT) {
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm.x = 0.0;
    ra_output.torque_nm.y = 0.0;
    ra_output.torque_nm.z = 0.0;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

// 3. Calculate Error and Rate
adcs_quat_t q_rel = adcs_quat_multiply(&q_target_norm, &adcs_quat_conjugate(&q_curr_norm));

if (q_rel.w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}

double angle_half = acos(q_rel.w);
double angle_rad = 2.0 * angle_half;

adcs_vec3_t error_vec_e;
if (angle_rad < 1e-12) {
    error_vec_e.x = 0.0;
    error_vec_e.y = 0.0;
    error_vec_e.z = 0.0;
} else {
    double sin_half = sin(angle_half);
    double scale = 2.0 * angle_half / sin_half;
    error_vec_e.x = q_rel.x * scale;
    error_vec_e.y = q_rel.y * scale;
    error_vec_e.z = q_rel.z * scale;
}

double rate_mag = adcs_vec3_norm(ra_input.body_rate_rad_s);

// 4. Mode Transitions
int rate_in_coarse_window = (angle_rad <= ra_config.fine_enter_rad) && (rate_mag <= ra_config.rate_enter_rad_s);
int rate_in_fine_hold_window = (angle_rad <= ra_config.hold_enter_rad) && (rate_mag <= ra_config.hold_rate_rad_s);

switch (ra_state.mode) {
    case RA_OFF:
        if (rate_mag > ra_config.rate_enter_rad_s) {
            ra_state.mode = RA_RATE_DAMP;
        } else {
            ra_state.mode = RA_COARSE;
        }
        ra_state.transition_samples = 0;
        break;

    case RA_RATE_DAMP:
        if (rate_mag >= ra_config.rate_exit_rad_s) {
            ra_state.transition_samples = 0;
        } else if (rate_mag <= ra_config.rate_enter_rad_s) {
            ra_state.transition_samples++;
            if (ra_state.transition_samples >= ra_config.rate_samples) {
                ra_state.mode = RA_COARSE;
                ra_state.transition_samples = 0;
            }
        } else {
            ra_state.transition_samples = 0;
        }
        break;

    case RA_COARSE:
        if (rate_in_coarse_window) {
            ra_state.transition_samples++;
            if (ra_state.transition_samples >= ra_config.fine_samples) {
                ra_state.mode = RA_FINE;
                ra_state.transition_samples = 0;
                ra_state.integral_error_rad_s.x = 0.0;
                ra_state.integral_error_rad_s.y = 0.0;
                ra_state.integral_error_rad_s.z = 0.0;
            }
        } else {
            ra_state.transition_samples = 0;
        }
        break;

    case RA_FINE:
        if (angle_rad >= ra_config.fine_exit_rad || rate_mag >= ra_config.rate_exit_rad_s) {
            ra_state.mode = RA_COARSE;
            ra_state.transition_samples = 0;
            ra_state.integral_error_rad_s.x = 0.0;
            ra_state.integral_error_rad_s.y = 0.0;
            ra_state.integral_error_rad_s.z = 0.0;
        } else {
            if (rate_in_fine_hold_window) {
                ra_state.transition_samples++;
                if (ra_state.transition_samples >= ra_config.hold_samples) {
                    ra_state.mode = RA_HOLD;
                    ra_state.transition_samples = 0;
                }
            } else {
                ra_state.transition_samples = 0;
            }
        }
        break;

    case RA_HOLD:
        if (angle_rad >= ra_config.hold_exit_rad || rate_mag >= ra_config.hold_rate_exit_rad_s) {
            ra_state.mode = RA_FINE;
            ra_state.transition_samples = 0;
        } else {
            if (!rate_in_fine_hold_window) {
                 ra_state.transition_samples = 0;
            }
        }
        break;

    default:
        break;
}

// 5. Control Law Calculation
adcs_vec3_t torque_unlim = {0.0, 0.0, 0.0};
adcs_vec3_t torque_limited = {0.0, 0.0, 0.0};
unint32 sat_mask = 0U;

adcs_vec3_t current_integral = ra_state.integral_error_rad_s;
int use_integral = (ra_state.mode == RA_FINE || ra_state.mode == RA_HOLD);

if (use_integral) {
    adcs_vec3_t delta_i = adcs_vec3_scale(&error_vec_e, ra_config.dt_s);
    adcs_vec3_t new_i = adcs_vec3_add(&current_integral, &delta_i);

    new_i.x = ADCS_CLAMP(new_i.x, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    new_i.y = ADCS_CLAMP(new_i.y, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    new_i.z = ADCS_CLAMP(new_i.z, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);

    current_integral = new_i;
} else {
    current_integral.x = 0.0;
    current_integral.y = 0.0;
    current_integral.z = 0.0;
}

double kp_val = (ra_state.mode == RA_RATE_DAMP) ? 0.0 : ra_config.kp;

adcs_vec3_t term_p = adcs_vec3_scale(&error_vec_e, -kp_val);
adcs_vec3_t term_d = adcs_vec3_scale(ra_input.body_rate_rad_s, -ra_config.kd);
adcs_vec3_t term_i = adcs_vec3_scale(&current_integral, -ra_config.ki);

torque_unlim = adcs_vec3_add(&term_p, &term_d);
torque_unlim = adcs_vec3_add(&torque_unlim, &term_i);

// 6. Saturation Handling and Freeze Logic
adcs_actuator_limit_t limit;
limit.min_value = -ra_config.torque_limit_nm;
limit.max_value = ra_config.torque_limit_nm;

adcs_vec3_t term_i_old = adcs_vec3_scale(&ra_state.integral_error_rad_s, -ra_config.ki);
adcs_vec3_t torque_unlim_old = adcs_vec3_add(&term_p, &term_d);
torque_unlim_old = adcs_vec3_add(&torque_unlim_old, &term_i_old);

for (int i = 0; i < 3; i++) {
    double unlim_val = (i == 0) ? torque_unlim.x : (i == 1) ? torque_unlim.y : torque_unlim.z;
    double old_val = (i == 0) ? torque_unlim_old.x : (i == 1) ? torque_unlim_old.y : torque_unlim_old.z;

    double limited_val;
    adcs_limit_scalar(unlim_val, &limit, &limited_val);

    int is_sat = (fabs(limited_val) >= ra_config.torque_limit_nm);

    int freeze = 0;
    if (is_sat) {
        if (copysign(1.0, unlim_val) == copysign(1.0, old_val)) {
             if (fabs(unlim_val) > fabs(old_val)) {
                 freeze = 1;
             }
        }
    }

    if (freeze) {
        double old_axis_val = (i == 0) ? torque_unlim_old.x : (i == 1) ? torque_unlim_old.y : torque_unlim_old.z;
        double old_limited_axis_val;
        adcs_limit_scalar(old_axis_val, &limit, &old_limited_axis_val);

        if (i == 0) torque_limited.x = old_limited_axis_val;
        else if (i == 1) torque_limited.y = old_limited_axis_val;
        else torque_limited.z = old_limited_axis_val;

        sat_mask |= (1U << i);
    } else {
        if (i == 0) torque_limited.x = limited_val;
        else if (i == 1) torque_limited.y = limited_val;
        else torque_limited.z = limited_val;

        if (is_sat) {
            sat_mask |= (1U << i);
        }
    }
}

// 7. Update State and Output
if (use_integral) {
    ra_state.integral_error_rad_s = current_integral;
}

ra_state.bad_samples = 0;

ra_output.mode = ra_state.mode;
ra_output.error_angle_rad = angle_rad;
ra_output.rate_magnitude_rad_s = rate_mag;
ra_output.torque_nm = torque_limited;
ra_output.bad_samples = ra_state.bad_samples;
ra_output.saturation_mask = sat_mask;

